import copy
from datetime import datetime, timezone
from pathlib import Path
import unittest
from unittest.mock import patch
from urllib.parse import parse_qs, urlsplit

import streamlit as st
from streamlit.testing.v1 import AppTest

import activity_sources
import api_client
import calendar_import
import config
import database
import importers
import synthetic_data
import ui_components
import uniclubs_database
import uniclubs_export
import uniclubs_user


NOW = datetime(2026, 11, 16, 12)
SOURCE_CLOCK = datetime(2026, 11, 16, 10, tzinfo=timezone.utc)
ROOT = Path(__file__).resolve().parents[1]
APP_TIMEOUT = 180
SOURCE_ID = 'uniclubs:starter-fixture'
SERIES_ID = 'uniclubs-series:starter-fixture'
SOURCE_TITLE = 'Starter fixture club workshop'


def values(elements):
    """Read actual native element text without depending on badge Markdown formatting."""
    return [element.value for element in elements]


def source_records():
    """Return one synthetic published, bookable event with a dependable future time slot."""
    club = {'external_id': 'starter-fixture-club', 'name': 'Starter Fixture Club',
            'source_url': 'https://uniclubs.ch/hsg/clubs/starter-fixture-club'}
    event = {
        'external_id': 'starter-fixture', 'club_external_id': 'starter-fixture-club',
        'title': SOURCE_TITLE, 'start_utc': '2026-11-17T19:00:00Z',
        'end_utc': '2026-11-17T20:00:00Z', 'location': 'SQUARE', 'event_type': 'workshop',
        'publication_status': 'published', 'availability_state': 'open',
        'requires_membership': False,
        'source_url': 'https://uniclubs.ch/hsg/clubs/starter-fixture-club/events/starter-fixture',
    }
    return [club], [event]


class StarterScenario(unittest.TestCase):
    """Follow a fresh published catalogue through two source types and a private profile reset."""

    original_seed = None
    original_bytes = None

    def setUp(self):
        """Freeze the clock, replace external reads and preserve the actual seed bytes."""
        if config.DATA_DIR == ROOT / 'data':
            raise RuntimeError('Run python -m views.check_starter with disposable paths.')
        self.connection = None
        self.links = []
        self.addCleanup(self.close_resources)
        self.fixture = uniclubs_database.get_connection(':memory:')
        self.addCleanup(self.fixture.close)
        uniclubs_database.init_db(self.fixture)
        clubs, events = source_records()
        uniclubs_database.sync_catalog(self.fixture, clubs, events, now=SOURCE_CLOCK)
        self.document = uniclubs_export.build_export(self.fixture)
        self.link_button = st.link_button
        self.start_patch(config, 'local_now', side_effect=lambda now=None: now or NOW)
        self.start_patch(importers, 'fetch_public_uniclubs_feed', side_effect=self.fetch_document)
        self.start_patch(api_client, 'is_api_available', return_value=False)
        self.start_patch(api_client.requests, 'get', side_effect=AssertionError('External HTTP'))
        self.start_patch(importers, 'fetch_json', side_effect=AssertionError('External import'))
        self.start_patch(calendar_import, 'fetch_ics_text',
                         side_effect=AssertionError('External calendar'))
        self.start_patch(synthetic_data, 'generate_all',
                         side_effect=AssertionError('Published startup imported demo courses'))
        self.start_patch(synthetic_data, 'ensure_synthetic_data',
                         side_effect=AssertionError('Published startup created synthetic ratings'))
        self.start_patch(st, 'link_button', side_effect=self.capture_link)

    def start_patch(self, module, name, **arguments):
        """Register patch cleanup before invoking the real Streamlit script."""
        replacement = patch.object(module, name, **arguments)
        self.addCleanup(replacement.stop)
        return replacement.start()

    def fetch_document(self):
        """Return a separate complete fixture without any external network request."""
        return copy.deepcopy(self.document)

    def capture_link(self, label, url, *arguments, **keywords):
        """Keep native link widgets and record their exact source destinations."""
        self.links.append((label, url))
        return self.link_button(label, url, *arguments, **keywords)

    def close_resources(self):
        """Close test handles and cached resources before Windows removes temporary files."""
        if self.connection is not None:
            self.connection.close()
        if config.DB_FILE.exists():
            ui_components.cached_connection().close()
        ui_components.clear_data_caches()
        ui_components.cached_connection.clear()
        ui_components.cached_uniclubs_refresh.clear()

    def clean(self):
        """Reject both uncaught exceptions and errors caught by the actual page handlers."""
        self.assertFalse(self.app.exception, values(self.app.exception))
        self.assertFalse(self.app.error, values(self.app.error))

    def new_session(self):
        """Open the actual shell against the same isolated persistent source files."""
        self.app = AppTest.from_file(str(ROOT / 'app.py'), default_timeout=APP_TIMEOUT).run()
        self.clean()

    def details(self, event_id):
        """Requeue a details dialog because AppTest reruns scripts rather than browser fragments."""
        self.links.clear()
        self.app.session_state['ww_open_event_id'] = event_id
        self.app.run()
        self.clean()

    def snapshot(self):
        """Read stable selected source values without including private profile settings."""
        statements = ('SELECT * FROM series ORDER BY id',
                      'SELECT * FROM events ORDER BY id',
                      'SELECT * FROM event_provenance ORDER BY event_id')
        result = []
        for statement in statements:
            result.append([tuple(row) for row in self.connection.execute(statement)])
        return result

    def assert_public_seed_unchanged(self):
        """Ensure neither the committed seed nor its test copy receives app writes."""
        self.assertEqual(self.original_seed.read_bytes(), self.original_bytes)
        self.assertEqual(config.PUBLIC_UNISPORT_SEED.read_bytes(), self.original_bytes)

    def assert_sport_counts(self):
        """Require the complete public sport catalogue and empty raw-data tables."""
        self.assertEqual(database.get_provenance_counts(self.connection),
                         {'website': 967, 'projected': 85, 'unspecified': 0})
        checks = (('SELECT COUNT(*) FROM series', 263), ('SELECT COUNT(*) FROM events', 1052),
                  ('SELECT COUNT(*) FROM training_history', 0),
                  ('SELECT COUNT(*) FROM training_imports', 0),
                  ('SELECT COUNT(*) FROM users WHERE is_synthetic=1', 0),
                  ('SELECT COUNT(*) FROM interactions', 0),
                  ("SELECT COUNT(*) FROM series WHERE source='uniclubs'", 0))
        for statement, count in checks:
            self.assertEqual(self.connection.execute(statement).fetchone()[0], count)
        self.assertEqual(self.connection.execute('SELECT COUNT(*) FROM series WHERE title=?',
                         (config.UNREVIEWED_ACTIVITY_TITLE,)).fetchone()[0], 15)
        masked = self.connection.execute('''SELECT COUNT(*) FROM events e
            JOIN series s ON s.id=e.series_id
            JOIN event_provenance p ON p.event_id=e.id
            WHERE s.title=? AND p.kind='projected' ''',
            (config.UNREVIEWED_ACTIVITY_TITLE,)).fetchone()[0]
        self.assertEqual(masked, 60)

    def onboard(self, name='Alex'):
        """Complete real-mode onboarding without copying demo feedback or synthetic profiles."""
        self.assertEqual(self.app.title[0].value, 'Welcome to WeekWise')
        self.app.button(key='ww_welcome_next').click().run()
        self.clean()
        self.assertTrue(self.app.checkbox(key='ww_demo_history').disabled)
        self.assertFalse(self.app.checkbox(key='ww_demo_history').value)
        self.app.text_input(key='ww_onboarding_name').set_value(name)
        self.app.checkbox(key='ww_onboarding_career').check()
        self.app.button(key='ww_focus_next').click().run()
        self.app.button(key='ww_finish_onboarding').click().run()
        self.clean()
        self.user_id = database.get_current_user_id(self.connection)

    def check_mixed_display(self):
        """Keep integer sport IDs and namespaced club IDs separate in the shared calendar."""
        captions = values(self.app.sidebar.caption)
        self.assertIn('967 website checked · 85 provisional dates.', captions)
        self.assertTrue(any('UniClubs: 1 real events' in value for value in captions))
        self.assertEqual(self.app.session_state['ww_week_start'].isoformat(), '2026-11-16')
        events = ui_components.load_events(datetime(2026, 11, 16), datetime(2026, 12, 14))
        self.assertEqual(sum(type(event.event_id) is int for event in events), 1052)
        self.assertEqual(len(events), 1053)
        self.assertEqual(len({event.event_id for event in events}), 1053)
        self.assertEqual([event.event_id for event in events
                          if type(event.event_id) is str], [SOURCE_ID])
        self.assert_sport_counts()

    def check_sport_details(self):
        """Show both evidence kinds, dated links and disabled unknown-availability actions."""
        rows = self.connection.execute('''SELECT e.id,e.start_time,p.kind FROM events e
            JOIN event_provenance p ON p.event_id=e.id WHERE e.start_time>?
            ORDER BY e.id''', (database.to_db_text(NOW),)).fetchall()
        for kind, label in (('website', 'Website checked'), ('projected', 'Provisional')):
            event = next(row for row in rows if row['kind'] == kind)
            self.details(event['id'])
            self.assertTrue(self.app.button(key='ww_confirm_event').disabled)
            self.assertTrue(any(label in value for value in values(self.app.markdown)))
            expected_date = event['start_time'][:10]
            self.assertTrue(any(name == 'Official sport calendar'
                                and parse_qs(urlsplit(url).query).get('selectedDate')
                                == [expected_date] for name, url in self.links))
            captions = values(self.app.caption)
            if kind == 'website':
                self.assertTrue(any('Published date checked on' in text for text in captions))
                self.assertTrue(any(name == 'Verification source' for name, _ in self.links))
            else:
                self.assertTrue(any('not website checked' in text for text in captions))
        self.assertEqual(self.snapshot(), self.before)

    def plan_club_event(self):
        """Store a club favorite and confirmation privately without changing sport source rows."""
        self.details(SOURCE_ID)
        self.assertFalse(self.app.button(key='ww_confirm_event').disabled)
        self.app.session_state['ww_open_event_id'] = SOURCE_ID
        self.app.checkbox(key='ww_favorite_series_' + SOURCE_ID).check().run()
        self.clean()
        self.app.session_state['ww_open_event_id'] = SOURCE_ID
        self.app.button(key='ww_confirm_event').click().run()
        self.clean()
        self.assertEqual(activity_sources.get_interaction(
            self.connection, self.user_id, SOURCE_ID)['status'], 'confirmed')
        self.assertIn(SERIES_ID, activity_sources.get_profile(
            self.connection, self.user_id).favorite_series_ids)
        self.owner = activity_sources.profile_key(self.connection, self.user_id)
        self.assertEqual(self.snapshot(), self.before)
        self.assert_sport_counts()

    def restore_and_reload(self):
        """Retain both sources and private club plans through a new session and saved reload."""
        self.new_session()
        self.assertEqual(activity_sources.get_interaction(
            self.connection, self.user_id, SOURCE_ID)['status'], 'confirmed')
        self.app.switch_page('views/settings.py').run()
        self.app.session_state['ww_settings_tab'] = 'Data sources'
        self.app.run()
        self.clean()
        self.app.button(key='ww_refresh_sources').click().run()
        self.clean()
        self.assertTrue(any('Website check times are unchanged.' in text
                            for text in values(self.app.success)))
        self.assertEqual(self.snapshot(), self.before)
        self.assertEqual(activity_sources.get_interaction(
            self.connection, self.user_id, SOURCE_ID)['status'], 'confirmed')

    def reset_and_reonboard(self):
        """Clear only the owner's choices and prevent a recycled user ID inheriting club plans."""
        self.app.checkbox(key='ww_reset_confirm').check().run()
        self.app.button(key='ww_reset_data').click().run()
        self.clean()
        self.assertEqual(self.snapshot(), self.before)
        self.assertEqual(self.connection.execute('SELECT COUNT(*) FROM users').fetchone()[0], 0)
        private = uniclubs_user.get_connection(config.UNICLUBS_USER_DB_FILE)
        try:
            self.assertEqual(uniclubs_user.list_interactions(private, self.owner), [])
            self.assertEqual(uniclubs_user.get_favorites(private, self.owner),
                             {'series': set(), 'club': set()})
        finally:
            private.close()
        self.onboard('Sam')
        self.assertNotEqual(activity_sources.profile_key(self.connection, self.user_id), self.owner)
        self.assertIsNone(activity_sources.get_interaction(
            self.connection, self.user_id, SOURCE_ID))
        self.assertNotIn(SERIES_ID, activity_sources.get_profile(
            self.connection, self.user_id).favorite_series_ids)
        self.assertEqual(self.snapshot(), self.before)
        self.assert_sport_counts()

    def test_published_seed_and_independent_club_planning(self):
        """Verify fresh offline startup, shared display and owner-safe reset using the real seed."""
        self.assertFalse(config.DB_FILE.exists())
        self.new_session()
        self.connection = database.get_connection(config.DB_FILE)
        self.assert_sport_counts()
        self.assertEqual(self.connection.execute('SELECT COUNT(*) FROM users').fetchone()[0], 0)
        self.before = self.snapshot()
        self.onboard()
        self.check_mixed_display()
        self.check_sport_details()
        self.plan_club_event()
        self.restore_and_reload()
        self.reset_and_reonboard()
        self.assertEqual(self.connection.execute('PRAGMA integrity_check').fetchone()[0], 'ok')
        self.assertEqual(self.connection.execute('PRAGMA foreign_key_check').fetchall(), [])
        self.assert_public_seed_unchanged()
